-- Local development seed data — NOT a Flyway migration.
--
-- Lives outside db/migration/ on purpose so Flyway never picks it up. Loaded by hand,
-- never automatically. Content is AI-generated and human-reviewed through the app's own
-- ingestion pipeline; baking it into migrations would contradict that architecture.
--
-- TODO: stopgap. Cross-cutting demo/sample data should move to a dedicated demo-data
-- repository shared across developers, testers, and QA.
--
-- Conventions:
--   * Safe to run repeatedly.
--   * id and created_at are generated by the database — never supply them here.
--   * Keep parents before children so foreign keys resolve.
--
-- Assumes (confirm against the migrations — not enforced by this script):
--   * concept has a UNIQUE(name) constraint (the ON CONFLICT (name) below needs it).
--   * question.version / document.version / mark_scheme.version each have a DB default
--     (these raw inserts bypass Hibernate's version init and omit the column).
--   * question_attempt column is attempt_body (per the data model, §2.5).
--
-- Load (idempotent):
--   docker exec -i practiq-api-postgres-1 psql -U practiq -d practiq < src/main/resources/db/seed_local.sql
--
-- Hard reset (clean slate — drops rows no longer in this file):
--   docker exec -i practiq-api-postgres-1 psql -U practiq -d practiq -c 'TRUNCATE concept, question, document CASCADE;'

-- ---------------------------------------------------------------------------
-- Concepts
-- Board-agnostic, granular units of knowledge. Natural key: name.
-- ---------------------------------------------------------------------------
insert into concept (name, description)
values ('Scalars and Vectors',
        'Distinguishing quantities with magnitude only from those with both magnitude and direction.'),
       ('Speed and Velocity', 'Rate of change of distance versus rate of change of displacement, and how they differ.'),
       ('Acceleration', 'How the velocity of an object changes over time, including deceleration.'),
       ('Newton''s First Law', 'An object stays at rest or in uniform motion unless acted on by a resultant force.'),
       ('Newton''s Second Law', 'The resultant force on an object equals its mass multiplied by its acceleration.'),
       ('Hooke''s Law',
        'The extension of an elastic object is proportional to the force applied, up to the limit of proportionality.'),
       ('Energy Stores and Transfers',
        'How energy is held in stores and shifted between them during physical processes.'),
       ('Conservation of Energy', 'Energy cannot be created or destroyed, only transferred, stored, or dissipated.'),
       ('Electrical Charge and Current', 'Current as the rate of flow of charge around a closed circuit.'),
       ('Potential Difference', 'The energy transferred per unit charge between two points in a circuit.'),
       ('Wave Properties', 'Describing waves using amplitude, wavelength, frequency, and period.'),
       ('Diffraction', 'The spreading out of waves as they pass through a gap or around an obstacle.')
on conflict (name) do nothing;

-- ── Questions + mark schemes + origin ──────────────────────────────────────
-- Body, concept links, mark scheme AND origin are authored together, once, in the
-- staging table below — never as separate lists matched by a text key (that drift
-- silently linked nothing in an earlier version of this script). See D-016.
--
-- source/source_spec are GONE from question (D-036). Origin now lives in question_origin:
--   * authorship: AUTHORED (a human wrote it) | EXTRACTED (from a document) | GENERATED (AI).
--     These replace the old source values (SEED→AUTHORED, EXTRACTED→EXTRACTED, GENERATED→GENERATED).
--   * doc_key: the s3_key of the source document, present IFF authorship=EXTRACTED (the invariant).
--     null for AUTHORED and GENERATED. Extraction sources are APPROVED docs only (D-039).
--
-- mark_scheme is still deliberately null on some rows (D-018 — absent row, not null column).
--
-- All content is self-written. No past-paper prose — see the copyright rule.
create temporary table seed_questions as
select *
from (values ('Which of the following is a vector quantity?

- [ ] Speed
- [ ] Mass
- [x] Velocity
- [ ] Time',
              1, 'MCQ', 'APPROVED', array ['Scalars and Vectors'], 'AUTHORED', null::text,
              '**1 mark**

- **Velocity** (1)

*Velocity has both magnitude and direction. Speed, mass and time are scalars.*'),

             ('A car travels 150 m in 10 s. Calculate its average speed.',
              null, 'SHORT_ANSWER', 'APPROVED', array ['Speed and Velocity'], 'AUTHORED', null,
              '**2 marks**

- Correct substitution into `speed = distance / time` → `150 / 10` (1)
- `15 m/s` — unit required (1)

*Award both marks for a correct answer with no working.*'),

             ('A 900 kg car accelerates uniformly from rest to 24 m/s in 8 s. (a) Calculate the car''s acceleration. (b) Calculate the resultant force needed to produce this acceleration. (c) State one reason the force needed in practice would be greater than your answer to (b).',
              null, 'EXTENDED', 'PENDING', array ['Acceleration', 'Newton''s Second Law'],
              'EXTRACTED', 'uploads/aqa-physics-2019-mechanics.pdf', null),

             ('State Newton''s First Law.',
              2, 'SHORT_ANSWER', 'APPROVED', array ['Newton''s First Law'], 'AUTHORED', null,
              '**2 marks**

- An object remains at rest, or continues at constant velocity (1)
- unless acted on by a resultant force (1)

*Accept "zero resultant force" for the second mark. Do not accept "no force".*'),

             ('Two students investigate the relationship between force and acceleration for a trolley of constant mass. They apply increasing force to the trolley and measure its acceleration each time. (a) Sketch the shape of the graph you would expect if acceleration is plotted against force. (b) State the relationship between force and acceleration shown by this graph. (c) The trolley has a mass of 1.5 kg. Calculate the force needed to accelerate it at 4 m/s squared.',
              null, null, 'PENDING', array ['Newton''s Second Law', 'Acceleration'], 'GENERATED', null, null),

             ('A resultant force of 10 N acts on an object of mass 2 kg. What is the object''s acceleration?

- [ ] 0.2 m/s squared
- [ ] 2.5 m/s squared
- [x] 5 m/s squared
- [ ] 20 m/s squared',
              2, 'MCQ', 'APPROVED', array ['Newton''s Second Law'], 'AUTHORED', null,
              '**1 mark**

- **5 m/s squared** (1)

*From `a = F / m` → `10 / 2`.*'),

             ('A spring has a natural length of 12 cm. When a 2 N force is applied, it stretches to 15 cm. Calculate the spring constant, stating the correct unit.',
              null, 'SHORT_ANSWER', 'PENDING', array ['Hooke''s Law'],
              'EXTRACTED', 'uploads/aqa-physics-2019-mechanics.pdf', null),

             ('A student stretches a spring within its limit of proportionality by applying a force and measuring the extension. (a) State Hooke''s Law. (b) The spring has a spring constant of 40 N/m and is extended by 0.05 m. Calculate the elastic potential energy stored in the spring. (c) State what happens to this stored energy if the spring is released and allowed to return to its natural length with nothing attached.',
              3, 'EXTENDED', 'APPROVED', array ['Hooke''s Law', 'Energy Stores and Transfers'], 'AUTHORED', null,
              '**5 marks**

**(a)** Extension is directly proportional to the force applied (1), up to the limit of proportionality (1)

**(b)** `E = 0.5 × k × e²` → `0.5 × 40 × 0.05²` (1) = `0.05 J` (1)

**(c)** Transferred to the kinetic energy store of the spring as it recoils, then dissipated to the thermal store of the surroundings (1)

*(b): allow error carried forward from an incorrect substitution. Unit required for the final mark.*'),

             ('A ball is thrown upwards and reaches its highest point. Which energy store increased as the ball rose?

- [ ] Kinetic
- [x] Gravitational potential
- [ ] Chemical
- [ ] Thermal',
              1, 'MCQ', 'APPROVED', array ['Energy Stores and Transfers'], 'AUTHORED', null, null),

             ('A skier of mass 60 kg starts from rest at the top of a slope 20 m high and reaches the bottom with a speed of 18 m/s. (a) Calculate the gravitational potential energy the skier had at the top of the slope, taking g = 10 N/kg. (b) Calculate the kinetic energy the skier has at the bottom. (c) Use the principle of conservation of energy to explain why your answers to (a) and (b) are not equal, and state where the missing energy has gone.',
              4, 'EXTENDED', 'APPROVED', array ['Conservation of Energy', 'Energy Stores and Transfers'],
              'GENERATED', null,
              '**6 marks**

**(a)** `E = m × g × h` → `60 × 10 × 20` (1) = `12 000 J` (1)

**(b)** `E = 0.5 × m × v²` → `0.5 × 60 × 18²` (1) = `9 720 J` (1)

**(c)** Energy is conserved, so the difference of `2 280 J` has not been destroyed (1). It has been dissipated to the thermal store of the surroundings by friction and air resistance (1)

*(c): accept "transferred to thermal/internal energy by friction". Do not accept "lost" or "used up" alone.*'),

             ('A charge of 15 C flows past a point in a wire in 5 s. Calculate the current in the wire.',
              2, 'SHORT_ANSWER', 'APPROVED', array ['Electrical Charge and Current'], 'AUTHORED', null,
              '**2 marks**

- Correct substitution into `I = Q / t` → `15 / 5` (1)
- `3 A` — unit required (1)'),

             ('What is the unit of electric current?

- [x] Ampere
- [ ] Coulomb
- [ ] Volt
- [ ] Watt',
              1, 'MCQ', 'REJECTED', array ['Electrical Charge and Current'],
              'EXTRACTED', 'uploads/aqa-physics-2007-p1.pdf', null),

             ('A battery transfers 24 J of energy to 4 C of charge as it flows through a circuit. (a) Define potential difference. (b) Calculate the potential difference of the battery. (c) Explain, in terms of energy, what a voltmeter placed across a component in the circuit is measuring.',
              3, 'EXTENDED', 'APPROVED', array ['Potential Difference', 'Electrical Charge and Current'], 'AUTHORED',
              null,
              '**4 marks**

**(a)** The energy transferred per unit charge between two points (1)

**(b)** `V = E / Q` → `24 / 4` = `6 V` (1)

**(c)** The energy transferred per coulomb of charge (1) as it passes through that component (1)

*(a): accept "energy per coulomb". Do not accept "the push" or "the force".*'),

             ('The diagram below shows a transverse wave.

{{s3:diagrams/transverse-wave.svg}}

(a) Use the diagram to state the amplitude of the wave in the units shown. (b) State the wavelength of the wave in the units shown.',
              2, 'SHORT_ANSWER', 'APPROVED', array ['Wave Properties'],
              'EXTRACTED', 'uploads/aqa-physics-2007-p1.pdf',
              '**2 marks**

**(a)** `3 cm` (1) — allow 2.8 to 3.2

**(b)** `8 cm` (1) — allow 7.8 to 8.2

*(a): do not credit peak-to-trough distance (6 cm) — amplitude is measured from the rest position.*'),

             ('A wave has a frequency of 50 Hz and a wavelength of 4 m. What is its wave speed?

- [ ] 12.5 m/s
- [x] 200 m/s
- [ ] 0.08 m/s
- [ ] 54 m/s',
              2, 'MCQ', 'APPROVED', array ['Wave Properties'], 'AUTHORED', null,
              '**1 mark**

- **200 m/s** (1)

*From `v = f × λ` → `50 × 4`.*'),

             ('The diagram below shows plane waves approaching a barrier with a narrow gap.

{{s3:diagrams/diffraction-gap.svg}}

(a) Describe what happens to the waves as they pass through the gap. (b) State how the amount of diffraction would change if the gap were made narrower, relative to the wavelength of the waves.',
              null, 'EXTENDED', 'PENDING', array ['Diffraction', 'Wave Properties'],
              'EXTRACTED', 'uploads/aqa-physics-2007-p1.pdf',
              null)) as t(body, difficulty, type, status, concept_names, authorship, doc_key, mark_scheme);

-- ── Idempotent clear-out: children before parents ──────────────────────────
-- Runs before the document delete below, so no question_origin row still points at a
-- document we're about to remove (document_id has no ON DELETE action — documents
-- soft-delete to REMOVED, they're never hard-deleted; D-036).
--
-- question_concept and question_origin cascade from question (ON DELETE CASCADE).
-- question_attempt and mark_scheme are cleared explicitly so this script does not depend
-- on their FK cascade behaviour.
delete
from question_attempt
where question_id in (select id from question where body in (select body from seed_questions));

delete
from mark_scheme
where question_id in (select id from question where body in (select body from seed_questions));

delete
from question
where body in (select body from seed_questions);

-- ── Documents ──────────────────────────────────────────────────────────────
-- Uploaded source artefacts + their approval gate (D-039). No processing state here —
-- that lives in document_processing_job, which doesn't exist yet.
--
-- Deliberate spread:
--   * All four status values present (UNAPPROVED / APPROVED / REJECTED / REMOVED) so the
--     approval gate is visible locally and "only APPROVED gets processed" is checkable.
--   * source_spec populated on most, null on one — it's an optional upload hint, not
--     mandatory, so the null path is exercised.
--   * s3_key is UNIQUE (natural key, D-040) — keys are distinct and opaque-ish.
--
-- The two APPROVED docs are the extraction sources the EXTRACTED question_origin rows
-- above point at (extraction only runs on APPROVED — D-039).
--
-- Safe to delete now: the question clear-out above already removed any origin rows that
-- referenced these documents. Idempotent: delete by s3_key (the natural key) before reinsert.
delete
from document
where s3_key in ('uploads/aqa-physics-2007-p1.pdf',
                 'uploads/aqa-physics-2019-mechanics.pdf',
                 'uploads/edexcel-physics-waves-2021.pdf',
                 'uploads/ocr-energy-worksheet.docx',
                 'uploads/unbranded-scan-batch-04.pdf',
                 'uploads/duplicate-upload-2007-p1.pdf');

insert into document (s3_key, filename, source_spec, status)
values ('uploads/aqa-physics-2007-p1.pdf', 'AQA_Physics_2007_Paper1.pdf', 'AQA GCSE Physics 2007', 'APPROVED'),
       ('uploads/aqa-physics-2019-mechanics.pdf', 'AQA_Physics_2019_Mechanics.pdf', 'AQA GCSE Physics 2019',
        'APPROVED'),
       ('uploads/edexcel-physics-waves-2021.pdf', 'Edexcel_Waves_2021.pdf', 'Edexcel GCSE Physics 2021', 'UNAPPROVED'),
       ('uploads/ocr-energy-worksheet.docx', 'OCR_Energy_Worksheet.docx', 'OCR GCSE Physics', 'REJECTED'),
       ('uploads/unbranded-scan-batch-04.pdf', 'scan_batch_04.pdf', null, 'UNAPPROVED'),
       ('uploads/duplicate-upload-2007-p1.pdf', 'AQA_Physics_2007_Paper1_copy.pdf', 'AQA GCSE Physics 2007', 'REMOVED');

-- ── Insert questions, concept links, mark schemes, origin ──────────────────
-- One pass off the staging table. Rejoin to the generated question ids by body text
-- (bodies are unique). question_concept / mark_scheme / question_origin all hang off id.
with inserted as (
    insert into question (body, difficulty, type, status)
        select body, difficulty, type, status from seed_questions
        returning id, body),
     links as (
         insert into question_concept (question_id, concept_id)
             select i.id, c.id
             from inserted i
                      join seed_questions sq on sq.body = i.body
                      join concept c on c.name = any (sq.concept_names)
             on conflict do nothing),
     schemes as (
         insert into mark_scheme (question_id, body)
             select i.id, sq.mark_scheme
             from inserted i
                      join seed_questions sq on sq.body = i.body
             where sq.mark_scheme is not null)
insert
into question_origin (question_id, authorship, document_id)
select i.id,
       sq.authorship,
       d.id -- null when doc_key is null (AUTHORED/GENERATED); the join is left
from inserted i
         join seed_questions sq on sq.body = i.body
         left join document d on d.s3_key = sq.doc_key;

drop table seed_questions;

-- ── Question attempts ──────────────────────────────────────────────────────
-- Anonymous attempts keyed by session_token (a client-generated UUID, D-020).
-- Matched to questions by body text, same pattern as above — no separate id list.
--
-- Deliberately shaped to exercise what GET /questions/{id}/attempts must do:
--   * Two sessions (A, B) so filtering by X-Session-Token is observable — session A
--     sees its own attempts only, never B's.
--   * Multiple attempts at ONE question by ONE session (the revision loop — the exact
--     case D-021 says must NOT be blocked by a unique constraint).
--   * created_at set explicitly with clear gaps so "newest first" is unambiguous when
--     eyeballed — the one place a DB now() default would make ordering untestable by hand.
--
-- Old attempt rows were already cleared by the question clear-out above; this just rebuilds.
-- Answer text goes into question_attempt.attempt_body (per the data model, §2.5).
--
-- Session tokens are readable fixed UUIDs — paste straight into an X-Session-Token header:
--   Session A: 11111111-1111-1111-1111-111111111111
--   Session B: 22222222-2222-2222-2222-222222222222

create temporary table seed_attempts as
select *
from (values
          -- Session A — three attempts at the same speed question: the revision loop, improving each time
          ('A car travels 150 m in 10 s. Calculate its average speed.',
           '11111111-1111-1111-1111-111111111111', 'speed = 150 / 10', timestamptz '2026-01-10 09:00:00+00'),
          ('A car travels 150 m in 10 s. Calculate its average speed.',
           '11111111-1111-1111-1111-111111111111', 'speed = distance / time = 150 / 10 = 15',
           timestamptz '2026-01-10 09:05:00+00'),
          ('A car travels 150 m in 10 s. Calculate its average speed.',
           '11111111-1111-1111-1111-111111111111', 'speed = distance / time = 150 / 10 = 15 m/s',
           timestamptz '2026-01-10 09:12:00+00'),

          -- Session A — single attempts at two other questions
          ('State Newton''s First Law.',
           '11111111-1111-1111-1111-111111111111',
           'An object stays still or moving at constant speed unless a force acts on it.',
           timestamptz '2026-01-10 09:20:00+00'),
          ('Which of the following is a vector quantity?

- [ ] Speed
- [ ] Mass
- [x] Velocity
- [ ] Time',
           '11111111-1111-1111-1111-111111111111', 'Velocity', timestamptz '2026-01-10 09:25:00+00'),

          -- Session B — different session, same speed question + one other. Proves GET filters by token.
          ('A car travels 150 m in 10 s. Calculate its average speed.',
           '22222222-2222-2222-2222-222222222222', 'Its 15', timestamptz '2026-01-11 14:00:00+00'),
          ('A charge of 15 C flows past a point in a wire in 5 s. Calculate the current in the wire.',
           '22222222-2222-2222-2222-222222222222', 'I = Q/t = 15/5 = 3A',
           timestamptz '2026-01-11 14:08:00+00')) as t(question_body, session_token, attempt_body, created_at);

insert into question_attempt (question_id, session_token, attempt_body, created_at)
select q.id, sa.session_token, sa.attempt_body, sa.created_at
from seed_attempts sa
         join question q on q.body = sa.question_body;

drop table seed_attempts;
